// Colormap tables, 256 entries, 8-bit sRGB, hex-packed. Generated by sampling the published colormaps at 256 equal steps
// and rounding to 8 bits (matplotlib 3.11.2, cmocean 3.0.3; viridis, inferno, cividis, balance on 2026-11-06; plasma,
// magma, twilight, gray on 2026-11-18 with the same rule, which reproduces the 2026-11-06 viridis table byte for byte);
// see apps/web/NOTICE.
// viridis, inferno, plasma, magma: BIDS mpl-colormaps (CC0). cividis (Nunez, Anderton, Renslow 2018): as distributed in
// matplotlib (matplotlib licence, BSD-style); a separate licence for the table was not verified (DevLog-011 s.5).
// twilight (cyclic): contributed to matplotlib by GitHub user bastibe, matplotlib pull request #6254 (closed 2018-05-28,
// https://github.com/matplotlib/matplotlib/pull/6254, accessed 2026-11-18), distributed under the matplotlib licence; no
// separate licence or author name is stated in that pull request, _cm_listed.py or the 3.0 release notes. gray: linear ramp.
// balance (diverging, signed quantities): cmocean, Copyright (c) 2015 Kristen M. Thyng, MIT licence.

export type ColormapName = 'viridis' | 'cividis' | 'inferno' | 'plasma' | 'magma' | 'balance' | 'twilight' | 'gray';
export const COLORMAPS: ColormapName[] = ['viridis', 'cividis', 'inferno', 'plasma', 'magma', 'balance', 'twilight', 'gray'];
export const DIVERGING: ReadonlySet<ColormapName> = new Set(['balance']);
/** cyclic maps (equal colour at both ends): phase */
export const CYCLIC: ReadonlySet<ColormapName> = new Set(['twilight']);

const HEX: Record<ColormapName, string> = {
	viridis: '',
	cividis: '',
	inferno: '',
	balance: '',
	plasma: '',
	magma: '',
	twilight: '',
	gray: '',
};

const cache = new Map<string, Uint8Array>();

/** RGBA8 table (256 x 4). */
export function colormapLut(name: ColormapName, reverse = false): Uint8Array {
	const key = name + (reverse ? ':r' : '');
	const hit = cache.get(key);
	if (hit) return hit;
	const h = HEX[name];
	const lut = new Uint8Array(1024);
	for (let i = 0; i < 256; i++) {
		const j = reverse ? 255 - i : i;
		for (let c = 0; c < 3; c++) lut[4 * i + c] = parseInt(h.slice(6 * j + 2 * c, 6 * j + 2 * c + 2), 16);
		lut[4 * i + 3] = 255;
	}
	cache.set(key, lut);
	return lut;
}

/** CSS gradient stops for the colorbar (17 stops). */
export function cssGradient(name: ColormapName, reverse = false, dir = 'to top'): string {
	const lut = colormapLut(name, reverse);
	const stops: string[] = [];
	for (let k = 0; k <= 16; k++) {
		const i = Math.min(255, Math.round((k / 16) * 255));
		stops.push(`rgb(${lut[4 * i]},${lut[4 * i + 1]},${lut[4 * i + 2]}) ${((100 * k) / 16).toFixed(2)}%`);
	}
	return `linear-gradient(${dir}, ${stops.join(', ')})`;
}
